create temporary table _seed on commit drop as
select $seed$[{"id":"thought_example_1","text":"I moved to a new city three weeks ago. My apartment is completely quiet and I haven't heard my own voice out loud today.","timestamp":"2026-10-05T08:30:00.000Z","rotation":-1.5,"x":-125,"y":-482,"width":300,"variant":"teal","emotion":"lonely","authorId":"user_seed_1","responses":[{"id":"reply_ex_1_1","type":"note","content":"The first month in a new place is the quietest mountain to climb. You are making roots even when it feels like drifting.","timestamp":"2026-10-05T08:45:00.000Z","isAI":false,"authorId":"user_seed_2"},{"id":"reply_ex_1_2","type":"sticker","content":"sticker_hug","timestamp":"2026-10-05T09:02:00.000Z","isAI":false,"authorId":"user_seed_3"},{"id":"reply_ex_1_3","type":"note","content":"The silence can feel heavy, but this quiet space holds you until you find your rhythm. You are not alone tonight.","timestamp":"2026-10-05T09:15:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#9DB4FF","#3B4A8C","#1A2040"],"glow":0.85,"flicker":0.35,"shape":"tall","sound":{"mood":"night","instrument":"pad","key":"D minor","tempo":52},"caption":"quiet rain at midnight"},"showHelp":false,"isExample":true},{"id":"thought_example_2","text":"My grandmother taught me how to fold paper cranes when I was little. Today I folded one for her from an old grocery receipt.","timestamp":"2026-10-05T09:10:00.000Z","rotation":2.1,"x":-471,"y":118,"width":290,"variant":"warm","emotion":"grateful","authorId":"user_seed_4","responses":[{"id":"reply_ex_2_1","type":"note","content":"Those little rituals stay forever. She folds them with you in spirit.","timestamp":"2026-10-05T09:25:00.000Z","isAI":false,"authorId":"user_seed_5"},{"id":"reply_ex_2_2","type":"sticker","content":"sticker_heart","timestamp":"2026-10-05T09:30:00.000Z","isAI":false,"authorId":"user_seed_6"}],"aiStatus":"done","lantern":{"palette":["#D9F2B4","#8DBF5A","#3E5A22"],"glow":0.95,"flicker":0.45,"shape":"round","sound":{"mood":"chimes","instrument":"bells","key":"G major","tempo":64},"caption":"paper cranes and golden tea"},"showHelp":false,"isExample":true},{"id":"thought_example_3","text":"Waiting for test results tomorrow morning. My chest feels tight and my mind keeps preparing for storms that haven't arrived.","timestamp":"2026-10-05T10:00:00.000Z","rotation":-0.8,"x":-471,"y":-282,"width":310,"variant":"rose","emotion":"anxious","authorId":"user_seed_7","responses":[{"id":"reply_ex_3_1","type":"note","content":"Take one slow breath in with me. You do not have to live tomorrow tonight.","timestamp":"2026-10-05T10:14:00.000Z","isAI":false,"authorId":"user_seed_8"},{"id":"reply_ex_3_2","type":"note","content":"Your mind is trying so hard to protect you. It is okay to set the shield down for just ten minutes and rest.","timestamp":"2026-10-05T10:20:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#8FE3D8","#2A8C88","#123B3A"],"glow":0.75,"flicker":0.55,"shape":"diamond","sound":{"mood":"wind","instrument":"synth","key":"A minor","tempo":48},"caption":"a quiet breath in the dark"},"showHelp":false,"isExample":true},{"id":"thought_example_4","text":"Watered the little fiddle-leaf fig tree I thought was completely dead. Today a tiny bright green leaf broke through the dry soil.","timestamp":"2026-10-05T11:20:00.000Z","rotation":1.4,"x":-125,"y":318,"width":295,"variant":"warm","emotion":"hopeful","authorId":"user_seed_9","responses":[{"id":"reply_ex_4_1","type":"note","content":"Life waits quietly under the dirt. What a gentle little reminder for both of you.","timestamp":"2026-10-05T11:35:00.000Z","isAI":false,"authorId":"user_seed_10"},{"id":"reply_ex_4_2","type":"sticker","content":"sticker_leaf","timestamp":"2026-10-05T11:42:00.000Z","isAI":false,"authorId":"user_seed_11"}],"aiStatus":"done","lantern":{"palette":["#FFE7A3","#F2B544","#8A5A12"],"glow":0.9,"flicker":0.25,"shape":"paper","sound":{"mood":"ocean","instrument":"kalimba","key":"E major","tempo":58},"caption":"morning light on a new leaf"},"showHelp":false,"isExample":true},{"id":"thought_example_5","text":"It has been one year since my father passed away. I still find myself looking for him in the vegetable garden every Sunday afternoon.","timestamp":"2026-10-05T12:05:00.000Z","rotation":-2.3,"x":221,"y":-282,"width":315,"variant":"teal","emotion":"grieving","authorId":"user_seed_12","responses":[{"id":"reply_ex_5_1","type":"note","content":"Love doesn't vanish just because someone leaves. It lives in every plant he tended and every Sunday you remember.","timestamp":"2026-10-05T12:20:00.000Z","isAI":false,"authorId":"user_seed_13"},{"id":"reply_ex_5_2","type":"note","content":"Missing him this tenderly is proof of how deeply he loved you. This little flame stays lit for him tonight.","timestamp":"2026-10-05T12:30:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#C9A7FF","#5B3A8C","#24123D"],"glow":0.8,"flicker":0.3,"shape":"tall","sound":{"mood":"night","instrument":"pad","key":"C minor","tempo":44},"caption":"lavender and Sunday soil"},"showHelp":false,"isExample":true},{"id":"thought_example_6","text":"After months of doubting myself, I finally hit send on my manuscript draft today! My hands were trembling, but I did it.","timestamp":"2026-10-05T13:40:00.000Z","rotation":1.8,"x":221,"y":118,"width":300,"variant":"rose","emotion":"joyful","authorId":"user_seed_14","responses":[{"id":"reply_ex_6_1","type":"note","content":"Huge congratulations! Sending bravery across the sky. You poured your heart out and that is everything.","timestamp":"2026-10-05T13:55:00.000Z","isAI":false,"authorId":"user_seed_15"},{"id":"reply_ex_6_2","type":"sticker","content":"sticker_sparkle","timestamp":"2026-10-05T14:10:00.000Z","isAI":false,"authorId":"user_seed_16"}],"aiStatus":"done","lantern":{"palette":["#FFE08A","#FF9F43","#FF6B6B"],"glow":1,"flicker":0.4,"shape":"round","sound":{"mood":"chimes","instrument":"harp","key":"F major","tempo":72},"caption":"first page written by candlelight"},"showHelp":false,"isExample":true},{"id":"thought_example_7","text":"Sitting on the train watching everyone tap their screens. Sometimes it feels like we are all surrounded by a thousand people and yet completely solitary.","timestamp":"2026-10-05T14:15:00.000Z","rotation":-1.1,"x":-30,"y":-760,"width":305,"variant":"teal","emotion":"lonely","authorId":"user_seed_17","responses":[{"id":"reply_ex_7_1","type":"note","content":"I feel that same train solitude every commute. Look up next time — someone is probably looking for a friendly face too.","timestamp":"2026-10-05T14:30:00.000Z","isAI":false,"authorId":"user_seed_18"}],"aiStatus":"done","lantern":{"palette":["#9DB4FF","#3B4A8C","#1A2040"],"glow":0.78,"flicker":0.32,"shape":"paper","sound":{"mood":"night","instrument":"pad","key":"D minor","tempo":50},"caption":"windows on the evening train"},"showHelp":false,"isExample":true},{"id":"thought_example_8","text":"The barista remembered my name and drew a tiny smiling sun on the coffee lid. It carried me through an entire ten-hour shift.","timestamp":"2026-10-05T15:00:00.000Z","rotation":2.6,"x":-760,"y":175,"width":290,"variant":"warm","emotion":"grateful","authorId":"user_seed_19","responses":[{"id":"reply_ex_8_1","type":"note","content":"Tiny kindnesses are the real glue that holds the world together. Beautiful.","timestamp":"2026-10-05T15:15:00.000Z","isAI":false,"authorId":"user_seed_20"}],"aiStatus":"done","lantern":{"palette":["#D9F2B4","#8DBF5A","#3E5A22"],"glow":0.92,"flicker":0.28,"shape":"diamond","sound":{"mood":"chimes","instrument":"bells","key":"G major","tempo":60},"caption":"steaming coffee on a cold porch"},"showHelp":false,"isExample":true},{"id":"thought_example_9","text":"Starting a new job tomorrow after six months out of work. Terrified that I'll forget everything on day one.","timestamp":"2026-10-05T15:50:00.000Z","rotation":-0.6,"x":-665,"y":-504,"width":300,"variant":"rose","emotion":"anxious","authorId":"user_seed_21","responses":[{"id":"reply_ex_9_1","type":"note","content":"They hired you because of who you are, not because you memorized everything. You'll do wonderful.","timestamp":"2026-10-05T16:05:00.000Z","isAI":false,"authorId":"user_seed_22"},{"id":"reply_ex_9_2","type":"note","content":"Nerves just mean you care. Walk in, breathe slowly, and take it one hour at a time.","timestamp":"2026-10-05T16:20:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#8FE3D8","#2A8C88","#123B3A"],"glow":0.82,"flicker":0.42,"shape":"tall","sound":{"mood":"wind","instrument":"synth","key":"A minor","tempo":54},"caption":"quiet desk before sunrise"},"showHelp":false,"isExample":true},{"id":"thought_example_10","text":"Applied for the community grant today. Even if we don't get selected, this was the first time our little neighborhood came together to dream.","timestamp":"2026-10-05T16:40:00.000Z","rotation":1.2,"x":-220,"y":596,"width":310,"variant":"warm","emotion":"hopeful","authorId":"user_seed_23","responses":[{"id":"reply_ex_10_1","type":"note","content":"The dream itself changes the soil. Rooting for you and your community!","timestamp":"2026-10-05T16:55:00.000Z","isAI":false,"authorId":"user_seed_24"}],"aiStatus":"done","lantern":{"palette":["#FFE7A3","#F2B544","#8A5A12"],"glow":0.88,"flicker":0.38,"shape":"round","sound":{"mood":"ocean","instrument":"kalimba","key":"E major","tempo":62},"caption":"warm streetlights on brick walls"},"showHelp":false,"isExample":true},{"id":"thought_example_11","text":"Found my late mother's handwritten recipe card for apple spice cake tucked inside an old cookbook. The handwriting is so familiar it stopped my breath.","timestamp":"2026-10-05T17:10:00.000Z","rotation":-1.9,"x":510,"y":-339,"width":315,"variant":"teal","emotion":"grieving","authorId":"user_seed_25","responses":[{"id":"reply_ex_11_1","type":"note","content":"Bake it this weekend. The scent of cinnamon and nutmeg is like a hug from across time.","timestamp":"2026-10-05T17:25:00.000Z","isAI":false,"authorId":"user_seed_26"},{"id":"reply_ex_11_2","type":"note","content":"Ink carries a person's rhythm long after they rest. What a precious treasure to uncover.","timestamp":"2026-10-05T17:35:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#C9A7FF","#5B3A8C","#24123D"],"glow":0.84,"flicker":0.34,"shape":"paper","sound":{"mood":"night","instrument":"pad","key":"C minor","tempo":46},"caption":"cinnamon and yellowed parchment"},"showHelp":false,"isExample":true},{"id":"thought_example_12","text":"My seven-year-old sister told me today that my laugh is her favorite song in the whole world. I’m going to hold that close on heavy days.","timestamp":"2026-10-05T18:00:00.000Z","rotation":2.2,"x":415,"y":340,"width":295,"variant":"rose","emotion":"joyful","authorId":"user_seed_27","responses":[{"id":"reply_ex_12_1","type":"note","content":"Kids see right to the heart of what matters. Never let that laughter fade.","timestamp":"2026-10-05T18:15:00.000Z","isAI":false,"authorId":"user_seed_28"},{"id":"reply_ex_12_2","type":"sticker","content":"sticker_heart","timestamp":"2026-10-05T18:22:00.000Z","isAI":false,"authorId":"user_seed_29"}],"aiStatus":"done","lantern":{"palette":["#FFE08A","#FF9F43","#FF6B6B"],"glow":0.96,"flicker":0.36,"shape":"round","sound":{"mood":"chimes","instrument":"harp","key":"F major","tempo":68},"caption":"laughter echoing in the yard"},"showHelp":false,"isExample":true},{"id":"thought_example_13","text":"Ate dinner alone again tonight. Put on a video of people talking just so the room wouldn't feel so empty.","timestamp":"2026-10-05T01:00:00.000Z","rotation":-2.2,"x":142,"y":-1014,"width":300,"variant":"teal","emotion":"lonely","authorId":"user_seed_100","responses":[{"id":"reply_ex_13_1","type":"note","content":"I do that too. You're not the only one with a voice in the background tonight.","timestamp":"2026-10-05T01:12:00.000Z","isAI":false,"authorId":"user_seed_200"},{"id":"reply_ex_13_2","type":"sticker","content":"sticker_candle","timestamp":"2026-10-05T01:29:00.000Z","isAI":false,"authorId":"user_seed_201"},{"id":"reply_ex_13_3","type":"note","content":"That emptiness is real, and reaching out here counts. You're not alone tonight.","timestamp":"2026-10-05T01:46:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#A9BFFF","#3F4FA0","#161C3D"],"glow":0.55,"flicker":0.2,"shape":"tall","sound":{"mood":"rain","instrument":"piano","key":"D minor","tempo":54},"caption":"a lamp on a quiet table"},"showHelp":false,"isExample":true},{"id":"thought_example_14","text":"Everyone in my group chat has plans this weekend. Nobody asked if I wanted to come.","timestamp":"2026-10-06T06:13:00.000Z","rotation":1.6,"x":385,"y":-1228,"width":300,"variant":"teal","emotion":"lonely","authorId":"user_seed_101","responses":[{"id":"reply_ex_14_1","type":"note","content":"Being left out stings so much. Maybe ask one of them for a coffee next week? Sometimes people just forget.","timestamp":"2026-10-06T06:25:00.000Z","isAI":false,"authorId":"user_seed_204"},{"id":"reply_ex_14_2","type":"sticker","content":"sticker_hug","timestamp":"2026-10-06T06:42:00.000Z","isAI":false,"authorId":"user_seed_205"}],"aiStatus":"done","lantern":{"palette":["#9DB4FF","#34478F","#141A38"],"glow":0.45,"flicker":0.25,"shape":"round","sound":{"mood":"wind","instrument":"pad","key":"A minor","tempo":50},"caption":"a phone screen glowing alone"},"showHelp":false,"isExample":true},{"id":"thought_example_15","text":"My best friend moved abroad. We still text, but the time difference makes it feel like we live in different worlds.","timestamp":"2026-10-07T11:26:00.000Z","rotation":-0.8,"x":691,"y":-1388,"width":300,"variant":"teal","emotion":"lonely","authorId":"user_seed_102","responses":[{"id":"reply_ex_15_1","type":"note","content":"Distance changes the rhythm, not the friendship. A voice note when they wake up can feel like a hug.","timestamp":"2026-10-07T11:38:00.000Z","isAI":false,"authorId":"user_seed_208"},{"id":"reply_ex_15_2","type":"note","content":"Missing someone this much shows how much they matter. That bond is still there.","timestamp":"2026-10-07T11:55:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#B4C6FF","#4A5BB0","#1B2246"],"glow":0.6,"flicker":0.2,"shape":"paper","sound":{"mood":"ocean","instrument":"cello","key":"F major","tempo":56},"caption":"two time zones apart"},"showHelp":false,"isExample":true},{"id":"thought_example_16","text":"Third night in a row I've talked to no one but the delivery guy.","timestamp":"2026-10-05T16:39:00.000Z","rotation":2.4,"x":1048,"y":-1480,"width":300,"variant":"teal","emotion":"lonely","authorId":"user_seed_103","responses":[{"id":"reply_ex_16_1","type":"sticker","content":"sticker_moon","timestamp":"2026-10-05T16:51:00.000Z","isAI":false,"authorId":"user_seed_212"},{"id":"reply_ex_16_2","type":"note","content":"Hi. Now you've talked to me too. I hope tomorrow brings a real conversation.","timestamp":"2026-10-05T17:08:00.000Z","isAI":false,"authorId":"user_seed_213"}],"aiStatus":"done","lantern":{"palette":["#8EA8FF","#2E3F86","#121836"],"glow":0.4,"flicker":0.3,"shape":"tall","sound":{"mood":"night","instrument":"pad","key":"D minor","tempo":48},"caption":"one window lit at night"},"showHelp":false,"isExample":true},{"id":"thought_example_17","text":"My dog passed this morning. The house is so quiet without his paws on the floor.","timestamp":"2026-10-06T21:52:00.000Z","rotation":-1.4,"x":816,"y":-317,"width":300,"variant":"rose","emotion":"grieving","authorId":"user_seed_104","responses":[{"id":"reply_ex_17_1","type":"note","content":"They're family. Every quiet moment is filled with how much you loved him.","timestamp":"2026-10-06T22:04:00.000Z","isAI":false,"authorId":"user_seed_216"},{"id":"reply_ex_17_2","type":"sticker","content":"sticker_heart","timestamp":"2026-10-06T22:21:00.000Z","isAI":false,"authorId":"user_seed_217"},{"id":"reply_ex_17_3","type":"note","content":"I'm so sorry. The silence shows how much he filled your days.","timestamp":"2026-10-06T22:38:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#D2B4FF","#6440A0","#26133F"],"glow":0.5,"flicker":0.12,"shape":"round","sound":{"mood":"rain","instrument":"piano","key":"C minor","tempo":50},"caption":"a collar by the door"},"showHelp":false,"isExample":true},{"id":"thought_example_18","text":"I still have my grandma's voice note saved. I play it when I can't sleep.","timestamp":"2026-10-07T04:05:00.000Z","rotation":0.9,"x":1123,"y":-213,"width":300,"variant":"rose","emotion":"grieving","authorId":"user_seed_105","responses":[{"id":"reply_ex_18_1","type":"note","content":"Keep it forever. Her voice is a lantern of its own.","timestamp":"2026-10-07T04:17:00.000Z","isAI":false,"authorId":"user_seed_220"},{"id":"reply_ex_18_2","type":"sticker","content":"sticker_candle","timestamp":"2026-10-07T04:34:00.000Z","isAI":false,"authorId":"user_seed_221"}],"aiStatus":"done","lantern":{"palette":["#C9A7FF","#5B3A8C","#24123D"],"glow":0.55,"flicker":0.1,"shape":"tall","sound":{"mood":"night","instrument":"cello","key":"A minor","tempo":46},"caption":"her voice at midnight"},"showHelp":false,"isExample":true},{"id":"thought_example_19","text":"We lost the baby last month. People stopped asking, but I haven't stopped thinking about it.","timestamp":"2026-10-05T09:18:00.000Z","rotation":-2.2,"x":1414,"y":-28,"width":300,"variant":"rose","emotion":"grieving","authorId":"user_seed_106","responses":[{"id":"reply_ex_19_1","type":"note","content":"Your grief doesn't have a deadline. I'm holding space for you and your little one.","timestamp":"2026-10-05T09:30:00.000Z","isAI":false,"authorId":"user_seed_224"},{"id":"reply_ex_19_2","type":"note","content":"What you lost is real, even when the world moves on. You can grieve here as long as you need.","timestamp":"2026-10-05T09:47:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#BFA0F5","#553688","#211038"],"glow":0.45,"flicker":0.12,"shape":"paper","sound":{"mood":"rain","instrument":"pad","key":"D minor","tempo":44},"caption":"a small light kept safe"},"showHelp":false,"isExample":true},{"id":"thought_example_20","text":"Cleaned out my dad's garage today. Found his old radio still tuned to his station.","timestamp":"2026-10-06T14:31:00.000Z","rotation":1.6,"x":1672,"y":235,"width":300,"variant":"rose","emotion":"grieving","authorId":"user_seed_107","responses":[{"id":"reply_ex_20_1","type":"sticker","content":"sticker_note","timestamp":"2026-10-06T14:43:00.000Z","isAI":false,"authorId":"user_seed_228"},{"id":"reply_ex_20_2","type":"note","content":"Maybe leave it on that station for a while. Some things can stay just as he left them.","timestamp":"2026-10-06T15:00:00.000Z","isAI":false,"authorId":"user_seed_229"}],"aiStatus":"done","lantern":{"palette":["#D9C2FF","#6B4AA8","#2A1645"],"glow":0.5,"flicker":0.15,"shape":"round","sound":{"mood":"wind","instrument":"piano","key":"F major","tempo":52},"caption":"his station, still playing"},"showHelp":false,"isExample":true},{"id":"thought_example_21","text":"My little brother said his first full sentence today and it was 'I love you'. I'm not crying, you're crying.","timestamp":"2026-10-07T19:44:00.000Z","rotation":-0.8,"x":549,"y":616,"width":300,"variant":"warm","emotion":"joyful","authorId":"user_seed_108","responses":[{"id":"reply_ex_21_1","type":"sticker","content":"sticker_sparkle","timestamp":"2026-10-07T19:56:00.000Z","isAI":false,"authorId":"user_seed_232"},{"id":"reply_ex_21_2","type":"note","content":"That's the most perfect first sentence ever!","timestamp":"2026-10-07T20:13:00.000Z","isAI":false,"authorId":"user_seed_233"}],"aiStatus":"done","lantern":{"palette":["#FFE6A0","#FF9A55","#FF6B7A"],"glow":0.9,"flicker":0.6,"shape":"star","sound":{"mood":"birds","instrument":"bells","key":"G major","tempo":78},"caption":"the first words, the best words"},"showHelp":false,"isExample":true},{"id":"thought_example_22","text":"Got the call: I'm in remission. Six months of chemo and I finally get to ring the bell.","timestamp":"2026-10-05T02:57:00.000Z","rotation":2.4,"x":613,"y":933,"width":300,"variant":"warm","emotion":"joyful","authorId":"user_seed_109","responses":[{"id":"reply_ex_22_1","type":"note","content":"RING IT LOUD! So happy for you.","timestamp":"2026-10-05T03:09:00.000Z","isAI":false,"authorId":"user_seed_236"},{"id":"reply_ex_22_2","type":"sticker","content":"sticker_sun","timestamp":"2026-10-05T03:26:00.000Z","isAI":false,"authorId":"user_seed_237"},{"id":"reply_ex_22_3","type":"note","content":"What wonderful news. Six months of courage, and today you get to celebrate it.","timestamp":"2026-10-05T03:43:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#FFF0B0","#FFAB4A","#FF6F61"],"glow":0.95,"flicker":0.55,"shape":"star","sound":{"mood":"chimes","instrument":"bells","key":"E major","tempo":82},"caption":"ring the bell"},"showHelp":false,"isExample":true},{"id":"thought_example_23","text":"Danced in the kitchen with my mom to old songs tonight. Haven't laughed like that in years.","timestamp":"2026-10-06T07:10:00.000Z","rotation":-1.4,"x":598,"y":1278,"width":300,"variant":"warm","emotion":"joyful","authorId":"user_seed_110","responses":[{"id":"reply_ex_23_1","type":"sticker","content":"sticker_heart","timestamp":"2026-10-06T07:22:00.000Z","isAI":false,"authorId":"user_seed_240"},{"id":"reply_ex_23_2","type":"note","content":"Kitchen dancing is the best kind of dancing.","timestamp":"2026-10-06T07:39:00.000Z","isAI":false,"authorId":"user_seed_241"}],"aiStatus":"done","lantern":{"palette":["#FFE08A","#FF9F43","#FF6B6B"],"glow":0.85,"flicker":0.7,"shape":"round","sound":{"mood":"fire","instrument":"piano","key":"C major","tempo":86},"caption":"old songs, new laughter"},"showHelp":false,"isExample":true},{"id":"thought_example_24","text":"Day 30 sober. It's not easy, but this morning I watched the sunrise and actually felt it.","timestamp":"2026-10-07T12:23:00.000Z","rotation":0.9,"x":-392,"y":850,"width":300,"variant":"warm","emotion":"hopeful","authorId":"user_seed_111","responses":[{"id":"reply_ex_24_1","type":"note","content":"Thirty days is huge. That sunrise was yours.","timestamp":"2026-10-07T12:35:00.000Z","isAI":false,"authorId":"user_seed_244"},{"id":"reply_ex_24_2","type":"sticker","content":"sticker_sun","timestamp":"2026-10-07T12:52:00.000Z","isAI":false,"authorId":"user_seed_245"},{"id":"reply_ex_24_3","type":"note","content":"Feeling the sunrise is a sign you're coming back to yourself. Proud of you.","timestamp":"2026-10-07T13:09:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#FFEDB0","#F4BE52","#8E5F14"],"glow":0.75,"flicker":0.3,"shape":"tall","sound":{"mood":"birds","instrument":"flute","key":"D major","tempo":64},"caption":"thirty sunrises"},"showHelp":false,"isExample":true},{"id":"thought_example_25","text":"Booked my first therapy appointment. Terrified, but I think it's time.","timestamp":"2026-10-05T17:36:00.000Z","rotation":-2.2,"x":-635,"y":1064,"width":300,"variant":"warm","emotion":"hopeful","authorId":"user_seed_112","responses":[{"id":"reply_ex_25_1","type":"note","content":"Booking it is the hardest part, and you already did it.","timestamp":"2026-10-05T17:48:00.000Z","isAI":false,"authorId":"user_seed_248"},{"id":"reply_ex_25_2","type":"sticker","content":"sticker_leaf","timestamp":"2026-10-05T18:05:00.000Z","isAI":false,"authorId":"user_seed_249"}],"aiStatus":"done","lantern":{"palette":["#FFE7A3","#F2B544","#8A5A12"],"glow":0.7,"flicker":0.35,"shape":"paper","sound":{"mood":"wind","instrument":"piano","key":"F major","tempo":60},"caption":"the first brave step"},"showHelp":false,"isExample":true},{"id":"thought_example_26","text":"Started learning guitar at 34. My fingers hurt, but I played my first full song today.","timestamp":"2026-10-06T22:49:00.000Z","rotation":1.6,"x":-941,"y":1224,"width":300,"variant":"warm","emotion":"hopeful","authorId":"user_seed_113","responses":[{"id":"reply_ex_26_1","type":"note","content":"It's never too late. Play it again tomorrow!","timestamp":"2026-10-06T23:01:00.000Z","isAI":false,"authorId":"user_seed_252"},{"id":"reply_ex_26_2","type":"sticker","content":"sticker_note","timestamp":"2026-10-06T23:18:00.000Z","isAI":false,"authorId":"user_seed_253"}],"aiStatus":"done","lantern":{"palette":["#FFF3C4","#F7C85E","#93691A"],"glow":0.7,"flicker":0.4,"shape":"round","sound":{"mood":"fire","instrument":"piano","key":"G major","tempo":70},"caption":"sore fingers, first song"},"showHelp":false,"isExample":true},{"id":"thought_example_27","text":"The doctor said the surgery went well. Long road ahead, but there is a road.","timestamp":"2026-10-07T05:02:00.000Z","rotation":-0.8,"x":-1298,"y":1316,"width":300,"variant":"warm","emotion":"hopeful","authorId":"user_seed_114","responses":[{"id":"reply_ex_27_1","type":"note","content":"One step at a time on that road. Sending strength.","timestamp":"2026-10-07T05:14:00.000Z","isAI":false,"authorId":"user_seed_256"},{"id":"reply_ex_27_2","type":"note","content":"A long road is still a road forward. Rest when you need to; you're on your way.","timestamp":"2026-10-07T05:31:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#FFE19A","#EFAE3E","#875510"],"glow":0.8,"flicker":0.3,"shape":"tall","sound":{"mood":"chimes","instrument":"pad","key":"E major","tempo":62},"caption":"a road ahead"},"showHelp":false,"isExample":true},{"id":"thought_example_28","text":"A stranger paid for my groceries when my card got declined. I never got to say thank you properly.","timestamp":"2026-10-05T10:15:00.000Z","rotation":2.4,"x":-1066,"y":153,"width":300,"variant":"light","emotion":"grateful","authorId":"user_seed_115","responses":[{"id":"reply_ex_28_1","type":"note","content":"Maybe this lantern is your thank you. And someday you will pass it on.","timestamp":"2026-10-05T10:27:00.000Z","isAI":false,"authorId":"user_seed_260"},{"id":"reply_ex_28_2","type":"sticker","content":"sticker_hand","timestamp":"2026-10-05T10:44:00.000Z","isAI":false,"authorId":"user_seed_261"}],"aiStatus":"done","lantern":{"palette":["#E0F5C0","#95C463","#405D24"],"glow":0.7,"flicker":0.3,"shape":"round","sound":{"mood":"birds","instrument":"bells","key":"C major","tempo":68},"caption":"kindness at the checkout"},"showHelp":false,"isExample":true},{"id":"thought_example_29","text":"My roommate left soup outside my door when I was sick. Small thing, huge for me.","timestamp":"2026-10-06T15:28:00.000Z","rotation":-1.4,"x":-1373,"y":49,"width":300,"variant":"light","emotion":"grateful","authorId":"user_seed_116","responses":[{"id":"reply_ex_29_1","type":"sticker","content":"sticker_heart","timestamp":"2026-10-06T15:40:00.000Z","isAI":false,"authorId":"user_seed_264"},{"id":"reply_ex_29_2","type":"note","content":"Good roommates are a gift. Hope you feel better!","timestamp":"2026-10-06T15:57:00.000Z","isAI":false,"authorId":"user_seed_265"}],"aiStatus":"done","lantern":{"palette":["#D9F2B4","#8DBF5A","#3E5A22"],"glow":0.65,"flicker":0.3,"shape":"tall","sound":{"mood":"fire","instrument":"piano","key":"F major","tempo":60},"caption":"warm soup, warm heart"},"showHelp":false,"isExample":true},{"id":"thought_example_30","text":"Thankful for the teacher who stayed late to explain it a third time and never made me feel stupid.","timestamp":"2026-10-07T20:41:00.000Z","rotation":0.9,"x":-1664,"y":-136,"width":300,"variant":"light","emotion":"grateful","authorId":"user_seed_117","responses":[{"id":"reply_ex_30_1","type":"note","content":"Teachers like that change lives. Maybe write them a note?","timestamp":"2026-10-07T20:53:00.000Z","isAI":false,"authorId":"user_seed_268"},{"id":"reply_ex_30_2","type":"note","content":"That patience stayed with you, and now it shines here. Lovely.","timestamp":"2026-10-07T21:10:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#E6F8C8","#9ACB6A","#45652A"],"glow":0.7,"flicker":0.25,"shape":"paper","sound":{"mood":"chimes","instrument":"flute","key":"G major","tempo":64},"caption":"patience, the third time"},"showHelp":false,"isExample":true},{"id":"thought_example_31","text":"My little sister drew me a card that says 'you are my hero'. It's on my fridge forever now.","timestamp":"2026-10-05T03:54:00.000Z","rotation":-2.2,"x":-1922,"y":-399,"width":300,"variant":"light","emotion":"grateful","authorId":"user_seed_118","responses":[{"id":"reply_ex_31_1","type":"sticker","content":"sticker_star","timestamp":"2026-10-05T04:06:00.000Z","isAI":false,"authorId":"user_seed_272"},{"id":"reply_ex_31_2","type":"note","content":"You're clearly doing something right.","timestamp":"2026-10-05T04:23:00.000Z","isAI":false,"authorId":"user_seed_273"}],"aiStatus":"done","lantern":{"palette":["#D4EFA8","#86B850","#3A5520"],"glow":0.75,"flicker":0.35,"shape":"round","sound":{"mood":"birds","instrument":"bells","key":"D major","tempo":72},"caption":"a card on the fridge"},"showHelp":false,"isExample":true},{"id":"thought_example_32","text":"Exam in six hours and I can't sleep. My brain keeps replaying everything I don't know.","timestamp":"2026-10-06T08:07:00.000Z","rotation":1.6,"x":-799,"y":-780,"width":300,"variant":"teal","emotion":"anxious","authorId":"user_seed_119","responses":[{"id":"reply_ex_32_1","type":"note","content":"You know more than your tired brain says right now. Rest is studying too.","timestamp":"2026-10-06T08:19:00.000Z","isAI":false,"authorId":"user_seed_276"},{"id":"reply_ex_32_2","type":"note","content":"Your mind is trying to protect you. Close your eyes and let the facts rest; they will still be there.","timestamp":"2026-10-06T08:36:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#9CEBE0","#2E9490","#123E3C"],"glow":0.55,"flicker":0.8,"shape":"paper","sound":{"mood":"rain","instrument":"pad","key":"A minor","tempo":58},"caption":"six hours until dawn"},"showHelp":false,"isExample":true},{"id":"thought_example_33","text":"Have to tell my parents I'm switching majors. I've rehearsed it fifty times.","timestamp":"2026-10-07T13:20:00.000Z","rotation":-0.8,"x":-863,"y":-1097,"width":300,"variant":"teal","emotion":"anxious","authorId":"user_seed_120","responses":[{"id":"reply_ex_33_1","type":"note","content":"It's your life and your future. You've got this.","timestamp":"2026-10-07T13:32:00.000Z","isAI":false,"authorId":"user_seed_280"},{"id":"reply_ex_33_2","type":"sticker","content":"sticker_hand","timestamp":"2026-10-07T13:49:00.000Z","isAI":false,"authorId":"user_seed_281"}],"aiStatus":"done","lantern":{"palette":["#8FE3D8","#2A8C88","#123B3A"],"glow":0.55,"flicker":0.75,"shape":"tall","sound":{"mood":"wind","instrument":"flute","key":"D minor","tempo":62},"caption":"fifty rehearsals"},"showHelp":false,"isExample":true},{"id":"thought_example_34","text":"My heart races every time my phone buzzes. I don't even know what I'm scared of anymore.","timestamp":"2026-10-05T18:33:00.000Z","rotation":2.4,"x":-848,"y":-1442,"width":300,"variant":"teal","emotion":"anxious","authorId":"user_seed_121","responses":[{"id":"reply_ex_34_1","type":"note","content":"Maybe try silencing notifications for an hour. Your body deserves a break.","timestamp":"2026-10-05T18:45:00.000Z","isAI":false,"authorId":"user_seed_284"},{"id":"reply_ex_34_2","type":"note","content":"That racing heart is exhausting. You don't have to know what it's about to deserve calm.","timestamp":"2026-10-05T19:02:00.000Z","isAI":true}],"aiStatus":"done","lantern":{"palette":["#A6F0E6","#33A09A","#154543"],"glow":0.5,"flicker":0.85,"shape":"round","sound":{"mood":"ocean","instrument":"pad","key":"C minor","tempo":56},"caption":"breathing through the buzz"},"showHelp":false,"isExample":true},{"id":"thought_example_35","text":"First day back at work after burnout. Smiling on the outside, shaking on the inside.","timestamp":"2026-10-06T01:46:00.000Z","rotation":-1.4,"x":-749,"y":-1797,"width":300,"variant":"teal","emotion":"anxious","authorId":"user_seed_122","responses":[{"id":"reply_ex_35_1","type":"sticker","content":"sticker_leaf","timestamp":"2026-10-06T01:58:00.000Z","isAI":false,"authorId":"user_seed_288"},{"id":"reply_ex_35_2","type":"note","content":"Coming back takes courage. Be gentle with yourself this week.","timestamp":"2026-10-06T02:15:00.000Z","isAI":false,"authorId":"user_seed_289"}],"aiStatus":"done","lantern":{"palette":["#93E8DC","#2C8F8A","#11393A"],"glow":0.55,"flicker":0.7,"shape":"paper","sound":{"mood":"chimes","instrument":"piano","key":"F major","tempo":60},"caption":"steady hands, shaking heart"},"showHelp":false,"isExample":true}]$seed$::jsonb as data;

insert into public.thoughts
  (id, text, emotion, author_id, x, y, rotation, width, variant, ai_status, lantern, show_help, is_example, created_at)
select
  md5('ember-seed:' || (e->>'id'))::uuid,
  e->>'text',
  e->>'emotion',
  e->>'authorId',
  (e->>'x')::real,
  (e->>'y')::real,
  coalesce((e->>'rotation')::real, 0),
  coalesce((e->>'width')::int, 300),
  coalesce(e->>'variant', 'warm'),
  coalesce(e->>'aiStatus', 'done'),
  e->'lantern',
  false,
  true,
  (e->>'timestamp')::timestamptz
from _seed, jsonb_array_elements(_seed.data) e
on conflict (id) do nothing;

insert into public.replies (id, thought_id, type, content, is_ai, author_id, created_at, seeded)
select
  md5('ember-seed:' || (r->>'id'))::uuid,
  md5('ember-seed:' || (e->>'id'))::uuid,
  r->>'type',
  coalesce(r->>'content', ''),
  coalesce((r->>'isAI')::boolean, false),
  r->>'authorId',
  (r->>'timestamp')::timestamptz,
  true
from _seed, jsonb_array_elements(_seed.data) e, jsonb_array_elements(coalesce(e->'responses', '[]'::jsonb)) r
on conflict (id) do nothing;

-- Move every example into the flower and give each its feeling's colours (including the 12 from before).
update public.thoughts t
set x = (e->>'x')::real, y = (e->>'y')::real, rotation = coalesce((e->>'rotation')::real, 0),
    lantern = e->'lantern'
from _seed, jsonb_array_elements(_seed.data) e
where t.id = md5('ember-seed:' || (e->>'id'))::uuid;
